"""
HTML 템플릿 기반 리포트 생성 (WeasyPrint로 PDF 변환)
sample.pdf의 디자인을 재현
"""

def format_number(val, unit="천원") -> str:
    """숫자를 포맷팅"""
    if val is None:
        return "-"
    val = float(val)
    if unit == "천원":
        return f"{val:,.0f}"
    elif unit == "백만원":
        return f"{val/1000:,.0f}"
    elif unit == "억원":
        v = val / 100000
        return f"{v:,.1f}억원"
    elif unit == "%":
        return f"{val:.1f}%"
    elif unit == "원":
        return f"{val:,.0f}원"
    return f"{val:,.0f}"


def fn(val) -> str:
    """천원 단위 숫자 포맷"""
    return format_number(val, "천원")


def fp(val) -> str:
    """퍼센트 포맷"""
    if val is None:
        return "-"
    return f"{val:.2f}%"


def _svg_bar_chart(data_dict, title="", width=350, height=150, colors=None):
    """SVG 막대그래프 생성 (컴팩트). data_dict = {label: value, ...}"""
    if not data_dict or all(v is None for v in data_dict.values()):
        return ""
    items = [(k, v if v is not None else 0) for k, v in data_dict.items()]
    max_val = max(abs(v) for _, v in items) or 1
    bar_w = min(40, (width - 60) // len(items) - 8)
    chart_h = height - 40
    default_colors = ["#1B3A6B", "#2C5282", "#A37C3E", "#C9A961", "#4A7BA8", "#D4B582"]
    if not colors:
        colors = default_colors
    
    svg = f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:{width}px;height:auto;margin:4px 0;">'
    if title:
        svg += f'<text x="{width//2}" y="14" text-anchor="middle" font-size="11" font-weight="600" fill="#0F2847">{title}</text>'
    
    base_y = chart_h + 16
    start_x = 30
    gap = (width - 50) / len(items)
    
    for i, (label, val) in enumerate(items):
        x = start_x + i * gap + gap / 2 - bar_w / 2
        bar_h = abs(val) / max_val * (chart_h - 24) if max_val > 0 else 0
        color = colors[i % len(colors)]
        y = base_y - bar_h
        svg += f'<rect x="{x}" y="{y}" width="{bar_w}" height="{bar_h}" fill="{color}" rx="3" opacity="0.85"/>'
        val_text = f"{val:,.1f}%" if abs(val) < 1000 else f"{val:,.0f}"
        svg += f'<text x="{x + bar_w/2}" y="{y - 4}" text-anchor="middle" font-size="9" font-weight="600" fill="{color}">{val_text}</text>'
        svg += f'<text x="{x + bar_w/2}" y="{base_y + 12}" text-anchor="middle" font-size="8" fill="#666">{label}</text>'
    
    svg += f'<line x1="25" y1="{base_y}" x2="{width-5}" y2="{base_y}" stroke="#DDD" stroke-width="1"/>'
    svg += '</svg>'
    return svg


