def _valuation_page(valuation: dict, company: dict) -> str:
    """기업가치평가 페이지"""
    if not valuation:
        return ""
    
    total_val = valuation.get("기업가치", 0)
    per_share = valuation.get("1주당평가액", 0)
    shares = valuation.get("주식수", 0)
    
    # 미래 가치 예측 (연 5% 성장 가정)
    future_rows = ""
    base_val = total_val
    for i, yr_offset in enumerate([0, 2, 3, 5, 7, 12, 17, 22]):
        import datetime
        base_year = int(valuation.get("기준일", "2024")[:4])
        future_year = base_year + yr_offset
        future_val = base_val * (1.05 ** yr_offset)
        future_per = future_val / shares if shares else 0
        future_rows += f"""
        <tr>
            <td>{future_year}년</td>
            <td class="num">{format_number(future_val / 1000, '억원')}</td>
            <td class="num">{format_number(future_per, '원')}</td>
        </tr>"""
    
    return f"""
<div class="page content-page">
    <div class="page-header">
        <img src="{LOGO_SMALL}" class="header-logo" alt="RSV"/>
        <span class="section-badge">📈 기업가치평가</span>
        <span class="page-title-main">비상장주식 가치평가</span>
    </div>
    <div class="page-body">
        <div class="valuation-summary">
            <div class="val-box">
                <div class="val-label">기업가치</div>
                <div class="val-amount">{format_number(total_val / 1000, '억원')}</div>
            </div>
            <div class="val-box">
                <div class="val-label">1주당 주식가액</div>
                <div class="val-amount">{format_number(per_share, '원')}</div>
            </div>
        </div>
        <p class="val-basis">평가기준일 {valuation.get('기준일', '')}</p>
        
        <h3 class="subsection-title">◆ 연도별 기업가치 예상 추이</h3>
        <p class="val-note">※ 연 5% 성장률 가정 (상증세법상 보충적 평가방법 기준)</p>
        <table class="data-table financial-table">
            <thead>
                <tr><th>연도</th><th>기업가치</th><th>1주당 주식가액</th></tr>
            </thead>
            <tbody>{future_rows}</tbody>
        </table>
        
        <div class="info-box" style="margin-top:20px;">
            <strong>산출 근거</strong><br>
            순자산가치(1주당): {format_number(valuation.get('순자산가치_1주당', 0), '원')}<br>
            순손익가치(1주당): {format_number(valuation.get('순손익가치_1주당', 0), '원')}<br>
            1주당 평가액 = (순자산가치 × 2 + 순손익가치 × 3) ÷ 5
        </div>
    </div>
</div>
"""


def _credit_page(company: dict, credit: dict, ratios: dict = None, bs: dict = None, isc: dict = None) -> str:
    """신용등급 관리 페이지 - 안정성/수익성/활동성 동적 진단"""
    grade = credit.get("현재등급", company.get("기업신용등급", "-"))
    ew = company.get("EW등급", "-")
    
    cr_rows = ""
    for item in credit.get("현금흐름등급", []):
        cr_rows += f"<tr><td>{item.get('기준일자', '-')}</td><td>{item.get('등급', '-')}</td></tr>"
    
    # ─── 진단 로직 ────────
    stability_rows = ""    # 안정성/수익성
    activity_rows = ""     # 활동성 (회전율)
    summary_warnings = []
    
    if ratios:
        years_list = ratios.get("years", [])
        latest = years_list[0] if years_list else None
        
        def _get(key):
            v = ratios.get(key, {})
            if isinstance(v, dict) and latest:
                return v.get(latest)
            return None
        
        def _bs(key):
            v = (bs or {}).get(key, {})
            return v.get(latest) if isinstance(v, dict) and latest else None
        
        def _is(key):
            v = (isc or {}).get(key, {})
            return v.get(latest) if isinstance(v, dict) and latest else None
        
        # 활동성 지표 fallback 계산: ratios에 없으면 BS/IS에서 직접 계산
        def _calc_turnover(ratio_key, numerator_key, denom_keys):
            """회전율을 ratios에서 찾고, 없으면 BS/IS에서 계산"""
            v = _get(ratio_key)
            if v is not None and v > 0:
                return v, False  # 이미 계산됨
            # fallback: 직접 계산
            num = _is(numerator_key) if numerator_key in ['매출액', '매출원가'] else _bs(numerator_key)
            for dk in denom_keys:
                denom = _bs(dk) if dk in ['자산총계','자산','재고자산','매출채권','매입채무'] else _is(dk)
                if denom and denom > 0 and num:
                    return round(num / denom, 2), True  # 직접 계산함
            return None, False
        
        # ── 안정성 + 수익성 ──
        stability_checks = [
            ("부채비율", _get("부채비율"), 200, "200% 이하", 'lower_better', "재무 안정성", "차입금 축소 또는 자본 확충 필요"),
            ("유동비율", _get("유동비율"), 150, "150% 이상", 'higher_better', "단기 지급능력", "단기 지급능력 개선 시급"),
            ("자기자본비율", _get("자기자본비율"), 30, "30% 이상", 'higher_better', "자본 건전성", "자본 건전성 개선 시급"),
            ("영업이익률", _get("영업이익률"), 5, "5% 이상", 'higher_better', "수익성", "수익성 개선 필요"),
            ("ROE", _get("ROE"), 10, "10% 이상", 'higher_better', "자본 효율성", "자본 효율성 개선 필요"),
            ("ROA", _get("ROA"), 5, "5% 이상", 'higher_better', "자산 효율성", "자산 효율성 개선 필요"),
        ]
        
        for name, value, threshold, recommend, direction, category, action_text in stability_checks:
            if value is None:
                status, color, weight, action = "데이터 없음", "#8B6F3E", "500", "재무제표 데이터 보완 필요"
            else:
                is_good = (value <= threshold) if direction == 'lower_better' else (value >= threshold)
                if is_good:
                    status, color, weight = "양호 ✓", "#2E7D32", "700"
                    action = "현 수준 유지"
                else:
                    status, color, weight = "관리 필요 ⚠", "#C62828", "800"
                    gap = (value - threshold) if direction == 'lower_better' else (threshold - value)
                    suffix = "초과" if direction == 'lower_better' else "부족"
                    action = f"<strong style='color:#C62828;'>{abs(gap):.1f}%p {suffix}</strong> — {action_text}"
                    summary_warnings.append(name)
            
            value_disp = f"{value:.1f}%" if value is not None else "-"
            stability_rows += f"""<tr>
                <td class="bold-row">{name}</td>
                <td class="num">{value_disp}</td>
                <td class="num" style="color:#8B6F3E;">{recommend}</td>
                <td class="num" style="color:{color};font-weight:{weight};">{status}</td>
                <td style="text-align:left;font-size:12px;">{action}</td>
            </tr>"""
        
        # ── 활동성 지표 (회전율) ──
        # (지표명, ratios 키, BS/IS 분자, [BS/IS 분모 후보], 권장 회전율, 권장 표시, action 메시지)
        activity_checks = [
            ("총자산회전율", "총자산회전율", "매출액", ["자산총계", "자산"],
             1.0, "1.0회 이상", "자산 효율성 부족 → 유휴자산 매각·재투자 검토"),
            ("재고자산회전율", "재고자산회전율", "매출액", ["재고자산"],
             6.0, "6회 이상 (60일↓)", "재고 적체 → 재고 정리·판매 촉진 필요"),
            ("매출채권회전율", "매출채권회전율", "매출액", ["매출채권"],
             6.0, "6회 이상 (60일↓)", "대금 회수 지연 → 결제조건 개선·채권관리 강화"),
            ("매입채무회전율", "매입채무회전율", "매출원가", ["매입채무"],
             8.0, "8회 이상 (45일↓)", "지급 지연 발생 → 거래처 신뢰도 영향 우려"),
        ]
        
        for name, rkey, num_key, denom_keys, threshold, recommend, action_text in activity_checks:
            value, computed = _calc_turnover(rkey, num_key, denom_keys)
            
            if value is None or value <= 0:
                status, color, weight = "데이터 없음", "#8B6F3E", "500"
                action = "재무제표 항목 누락 (재고/채권/채무)"
                value_disp = "-"
                days_disp = "-"
            else:
                days = round(365 / value, 0) if value > 0 else 0
                is_good = value >= threshold
                if is_good:
                    status, color, weight = "양호 ✓", "#2E7D32", "700"
                    action = "현 수준 유지"
                else:
                    status, color, weight = "관리 필요 ⚠", "#C62828", "800"
                    gap_days = round(365 / threshold, 0)
                    action = f"<strong style='color:#C62828;'>약 {int(days)}일 소요</strong> (권장 {int(gap_days)}일↓) — {action_text}"
                    summary_warnings.append(name)
                
                value_disp = f"{value:.2f}회"
                if computed:
                    value_disp += " <span style='color:#8B6F3E;font-size:10px;font-weight:700;'>※자동계산</span>"
                days_disp = f"{int(days)}일"
            
            activity_rows += f"""<tr>
                <td class="bold-row">{name}</td>
                <td class="num">{value_disp}</td>
                <td class="num" style="color:#0F2847;font-weight:700;">{days_disp}</td>
                <td class="num" style="color:#8B6F3E;">{recommend}</td>
                <td class="num" style="color:{color};font-weight:{weight};">{status}</td>
                <td style="text-align:left;font-size:12px;">{action}</td>
            </tr>"""
    
    # 부족 항목 요약 박스
    if summary_warnings:
        warn_list = ", ".join(f"<strong style='color:#C62828;'>{w}</strong>" for w in summary_warnings)
        warning_summary = f'''<div class="warning-box" style="margin-top:8px;padding:10px 16px;font-size:12.5px;">
            ⚠️ <strong>등급 상승 위해 우선 관리 필요한 지표:</strong> {warn_list} <span style="color:#8B6F3E;">({len(summary_warnings)}개 항목)</span>
        </div>'''
    elif ratios:
        warning_summary = '''<div class="info-box" style="margin-top:8px;padding:10px 16px;font-size:12.5px;">
            ✓ <strong>주요 재무비율이 모두 권장 기준을 충족</strong>합니다. 비재무 요소(특허·인증·거래처 다변화) 강화로 한 단계 더 상승 가능합니다.
        </div>'''
    else:
        warning_summary = ''
    
    return f"""
<div class="page content-page">
    <div class="page-header">
        <img src="{LOGO_SMALL}" class="header-logo" alt="RSV"/>
        <span class="section-badge">🏦 신용등급 관리</span>
        <span class="page-title-main">기업 신용등급 현황 및 진단</span>
    </div>
    <div class="page-body">
        <div class="credit-summary" style="margin-bottom:8px;">
            <div class="credit-box" style="padding:18px;">
                <div class="credit-label">기업신용등급</div>
                <div class="credit-grade" style="font-size:42px;">{grade}</div>
            </div>
            <div class="credit-box" style="padding:18px;">
                <div class="credit-label">EW 등급</div>
                <div class="credit-grade ew-{ew}" style="font-size:42px;">{ew}</div>
            </div>
        </div>
        
        <h3 class="subsection-title" style="margin-top:6px;">◆ 안정성 · 수익성 진단</h3>
        <table class="data-table financial-table compact">
            <thead>
                <tr>
                    <th style="width:110px;">재무지표</th>
                    <th style="width:80px;">현재값</th>
                    <th style="width:100px;">권장 기준</th>
                    <th style="width:115px;">진단 결과</th>
                    <th>관리 방향</th>
                </tr>
            </thead>
            <tbody>{stability_rows if stability_rows else '<tr><td colspan="5" style="text-align:center;color:#8B6F3E;padding:14px;">재무비율 데이터를 불러올 수 없습니다.</td></tr>'}</tbody>
        </table>
        
        <h3 class="subsection-title" style="margin-top:8px;">◆ 활동성 진단 (자금 회전 효율)</h3>
        <table class="data-table financial-table compact">
            <thead>
                <tr>
                    <th style="width:115px;">회전율 지표</th>
                    <th style="width:115px;">현재값</th>
                    <th style="width:65px;">소요일</th>
                    <th style="width:115px;">권장 기준</th>
                    <th style="width:115px;">진단 결과</th>
                    <th>관리 방향</th>
                </tr>
            </thead>
            <tbody>{activity_rows if activity_rows else '<tr><td colspan="6" style="text-align:center;color:#8B6F3E;padding:14px;">활동성 데이터를 불러올 수 없습니다.</td></tr>'}</tbody>
        </table>
        
        {warning_summary}
        
        {f'''<h3 class="subsection-title" style="margin-top:8px;">◆ 현금흐름등급 이력</h3>
        <table class="data-table financial-table compact">
            <thead><tr><th>재무기준일자</th><th>등급</th></tr></thead>
            <tbody>{cr_rows}</tbody>
        </table>''' if cr_rows else ''}
    </div>
</div>
"""


