def _inheritance_tax_page(valuation: dict, company: dict) -> str:
    """상속세 계산 시뮬레이션 (비상장주식 기준)"""
    if not valuation:
        return ""
    
    total_val = valuation.get("기업가치", 0)  # 원 단위
    per_share = valuation.get("1주당평가액", 0)
    shares = valuation.get("주식수", 0) or 1
    company_name = company.get("기업명", "기업")
    
    def calc_inheritance_tax(taxable):
        """상속세 과세표준별 누진세율 계산 (만원 단위 입력 가능)"""
        if taxable <= 0:
            return 0
        # 누진세율 (억원 단위 기준)
        if taxable <= 100_000_000:  # 1억 이하
            tax = taxable * 0.10
        elif taxable <= 500_000_000:  # 5억 이하
            tax = 10_000_000 + (taxable - 100_000_000) * 0.20
        elif taxable <= 1_000_000_000:  # 10억 이하
            tax = 90_000_000 + (taxable - 500_000_000) * 0.30
        elif taxable <= 3_000_000_000:  # 30억 이하
            tax = 240_000_000 + (taxable - 1_000_000_000) * 0.40
        else:
            tax = 1_040_000_000 + (taxable - 3_000_000_000) * 0.50
        return tax
    
    # 시나리오: 지분 100%, 75%, 50%, 30% 상속
    scenarios = [100, 75, 50, 30]
    scenario_rows = ""
    for pct in scenarios:
        inherit_val = total_val * pct / 100
        # 기본공제 5억원 (일괄공제) + 배우자공제 5억원 가정 = 10억원 공제
        deduction = 1_000_000_000  # 10억
        taxable = max(inherit_val - deduction, 0)
        tax = calc_inheritance_tax(taxable)
        eff_rate = tax / inherit_val * 100 if inherit_val > 0 else 0
        scenario_rows += f"""
        <tr>
            <td class="bold-row">지분 {pct}% 상속</td>
            <td class="num">{inherit_val/100_000_000:,.1f}억원</td>
            <td class="num">{deduction/100_000_000:,.0f}억원</td>
            <td class="num">{taxable/100_000_000:,.1f}억원</td>
            <td class="num" style="color:#C62828;font-weight:700;">{tax/100_000_000:,.2f}억원</td>
            <td class="num">{eff_rate:.1f}%</td>
        </tr>"""
    
    # 미래 가치 기준 상속세 (5년, 10년 후)
    future_rows = ""
    for yrs in [0, 5, 10, 15]:
        future_val = total_val * (1.05 ** yrs)
        future_per = future_val / shares if shares else 0
        future_taxable = max(future_val - 1_000_000_000, 0)
        future_tax = calc_inheritance_tax(future_taxable)
        future_rows += f"""
        <tr>
            <td>{'현재' if yrs == 0 else f'{yrs}년 후'}</td>
            <td class="num">{future_val/100_000_000:,.1f}억원</td>
            <td class="num">{future_per:,.0f}원</td>
            <td class="num">{future_taxable/100_000_000:,.1f}억원</td>
            <td class="num" style="color:#C62828;font-weight:700;">{future_tax/100_000_000:,.2f}억원</td>
        </tr>"""
    
    # SVG 차트: 지분율별 상속세
    chart_data = {}
    for pct in scenarios:
        inherit_val = total_val * pct / 100
        taxable = max(inherit_val - 1_000_000_000, 0)
        chart_data[f"{pct}%"] = calc_inheritance_tax(taxable) / 100_000_000
    chart1 = _svg_bar_chart(chart_data, "지분율별 상속세 (억원)", 320, 140, ["#1B3A6B","#2C5282","#A37C3E","#C9A961"])
    
    # 시간별 상속세 차트
    time_data = {}
    for yrs in [0, 5, 10, 15]:
        future_val = total_val * (1.05 ** yrs)
        taxable = max(future_val - 1_000_000_000, 0)
        time_data[f"{yrs}년" if yrs > 0 else "현재"] = calc_inheritance_tax(taxable) / 100_000_000
    chart2 = _svg_bar_chart(time_data, "시간 경과별 상속세 (억원)", 320, 140, ["#4A7BA8","#2C5282","#1B3A6B","#0F2847"])
    
    return f"""
<div class="page content-page">
    <div class="page-header">
        <img src="{LOGO_SMALL}" class="header-logo" alt="RSV"/>
        <span class="section-badge">📈 기업가치평가</span>
        <span class="page-title-main">상속세 시뮬레이션</span>
    </div>
    <div class="page-body">
        <div class="info-box">
            <strong>{company_name}</strong>의 비상장주식을 <strong>상속</strong>할 경우 예상 세금을 산출합니다.
            평가기준액: <strong>{total_val/100_000_000:,.1f}억원</strong> (1주당 {per_share:,.0f}원 × {shares:,}주)
            / 공제 가정: 일괄공제 5억 + 배우자공제 5억 = <strong>10억원</strong>
        </div>
        
        <h3 class="subsection-title">◆ 지분율별 상속세 (현재가치 기준)</h3>
        <div style="display:flex;gap:16px;">
            <div style="flex:2;">
                <table class="data-table financial-table">
                    <thead>
                        <tr><th>구분</th><th>상속재산</th><th>공제</th><th>과세표준</th><th>상속세</th><th>실효세율</th></tr>
                    </thead>
                    <tbody>{scenario_rows}</tbody>
                </table>
            </div>
            <div style="flex:1;">{chart1}</div>
        </div>
        
        <h3 class="subsection-title" style="margin-top:12px;">◆ 시간 경과에 따른 상속세 (지분 100% / 연 5% 성장 가정)</h3>
        <div style="display:flex;gap:16px;">
            <div style="flex:2;">
                <table class="data-table financial-table">
                    <thead>
                        <tr><th>시점</th><th>기업가치</th><th>1주당</th><th>과세표준</th><th>예상 상속세</th></tr>
                    </thead>
                    <tbody>{future_rows}</tbody>
                </table>
            </div>
            <div style="flex:1;">{chart2}</div>
        </div>
        
        <div class="warning-box" style="margin-top:12px;">
            ⚠️ 본 시뮬레이션은 <strong>간이 계산</strong>입니다. 실제 상속세는 상속인 구성·공제항목·가산세·세액공제 등에 따라 달라지며, 
            비상장주식은 할증평가(최대 30%)가 적용될 수 있습니다. 반드시 세무사와 상담하시기 바랍니다.
        </div>
    </div>
</div>
"""


