def _retirement_plan_page(isc: dict, bs: dict, company: dict, years: list, year_labels: list, sim_params: dict = None) -> str:
    """예상 퇴직금 및 퇴직소득세 검토"""
    sp = sim_params or {}
    
    # 사용자 입력값 또는 추정
    ceo_salary_est = sp.get("monthly_salary", 1000) * 12  # 만원
    tenure_years = sp.get("tenure", 10)
    retire_year = sp.get("retire_year", 2035)
    multiplier = 3 if retire_year <= 2019 else 2
    
    severance_1x = ceo_salary_est / 12 * tenure_years
    severance_2x = severance_1x * 2
    severance_3x = severance_1x * 3
    
    # 퇴직소득세 계산 함수
    def calc_retire_tax(amt, yrs):
        if yrs <= 5: ded = yrs * 30
        elif yrs <= 10: ded = 150 + (yrs - 5) * 50
        elif yrs <= 20: ded = 400 + (yrs - 10) * 80
        else: ded = 1200 + (yrs - 20) * 120
        cs = max(amt - ded, 0) * 12 / yrs if yrs > 0 else 0
        if cs <= 800: cd = cs
        elif cs <= 7000: cd = 800 + (cs - 800) * 0.6
        elif cs <= 10000: cd = 4520 + (cs - 7000) * 0.55
        elif cs <= 30000: cd = 6170 + (cs - 10000) * 0.45
        else: cd = 15170 + (cs - 30000) * 0.35
        ctb = max(cs - cd, 0)
        if ctb <= 1400: ctx = ctb * 0.06
        elif ctb <= 5000: ctx = 84 + (ctb - 1400) * 0.15
        elif ctb <= 8800: ctx = 624 + (ctb - 5000) * 0.24
        elif ctb <= 15000: ctx = 1536 + (ctb - 8800) * 0.35
        else: ctx = 3706 + (ctb - 15000) * 0.38
        return round(ctx * yrs / 12 * 1.1) if yrs > 0 else 0
    
    sev = severance_2x if multiplier == 2 else severance_3x
    sev_tax = calc_retire_tax(sev, tenure_years)
    sev_net = sev - sev_tax
    sev_rate = sev_tax / sev * 100 if sev > 0 else 0
    
    # 퇴직금 그래프 미리 생성
    tax_1x = calc_retire_tax(severance_1x, tenure_years)
    tax_2x = calc_retire_tax(severance_2x, tenure_years)
    tax_3x = calc_retire_tax(severance_3x, tenure_years)
    retire_pretax_chart = _svg_bar_chart({"1배": severance_1x, "2배": severance_2x, "3배": severance_3x}, "배수별 퇴직금 (세전, 만원)", 320, 130, ["#4A7BA8","#2C5282","#1B3A6B"])
    retire_aftertax_chart = _svg_bar_chart({"1배": severance_1x - tax_1x, "2배": severance_2x - tax_2x, "3배": severance_3x - tax_3x}, "배수별 퇴직금 (세후, 만원)", 320, 130, ["#A37C3E","#8B6F3A","#1B3A6B"])
    
    return f"""
<div class="page content-page">
    <div class="page-header">
        <img src="{LOGO_SMALL}" class="header-logo" alt="RSV"/>
        <span class="section-badge">👔 임원소득보상플랜</span>
        <span class="page-title-main">예상 퇴직금 및 퇴직소득세 검토</span>
    </div>
    <div class="page-body">
        <div class="info-box" style="padding:10px 14px;font-size:13px;margin-bottom:10px;">
            <strong>현재 설정:</strong> 연봉 {ceo_salary_est:,.0f}만원 / 근속 {tenure_years}년 / 정관배수 <strong>{multiplier}배</strong> {'(2019년 이전 취임 → 3배)' if multiplier == 3 else '(2020년 이후 취임 → 2배)'}
            &nbsp;|&nbsp; 퇴직금 = 월평균급여 × 근속연수 × 정관배수
        </div>

        <h3 class="subsection-title">◆ 퇴직금 시뮬레이션</h3>
        
        <table class="data-table financial-table compact">
            <thead>
                <tr><th>구분</th><th>지급배수 1배</th><th>지급배수 2배</th><th>지급배수 3배</th></tr>
            </thead>
            <tbody>
                <tr>
                    <td class="bold-row">연봉 (직전3년 평균)</td>
                    <td class="num" colspan="3">{ceo_salary_est:,.0f}만원</td>
                </tr>
                <tr>
                    <td class="bold-row">근속기간</td>
                    <td class="num" colspan="3">{tenure_years}년</td>
                </tr>
                <tr>
                    <td class="bold-row">예상 퇴직금 (세전)</td>
                    <td class="num">{severance_1x:,.0f}만원</td>
                    <td class="num">{severance_2x:,.0f}만원</td>
                    <td class="num">{severance_3x:,.0f}만원</td>
                </tr>
                <tr>
                    <td class="bold-row">퇴직소득세</td>
                    <td class="num">{calc_retire_tax(severance_1x, tenure_years):,.0f}만원</td>
                    <td class="num">{calc_retire_tax(severance_2x, tenure_years):,.0f}만원</td>
                    <td class="num">{calc_retire_tax(severance_3x, tenure_years):,.0f}만원</td>
                </tr>
                <tr class="total-row">
                    <td class="bold-row">예상 퇴직금 (세후)</td>
                    <td class="num">{severance_1x - calc_retire_tax(severance_1x, tenure_years):,.0f}만원</td>
                    <td class="num">{severance_2x - calc_retire_tax(severance_2x, tenure_years):,.0f}만원</td>
                    <td class="num">{severance_3x - calc_retire_tax(severance_3x, tenure_years):,.0f}만원</td>
                </tr>
                <tr>
                    <td class="bold-row">실효세율</td>
                    <td class="num">{calc_retire_tax(severance_1x, tenure_years)/severance_1x*100 if severance_1x > 0 else 0:.1f}%</td>
                    <td class="num">{calc_retire_tax(severance_2x, tenure_years)/severance_2x*100 if severance_2x > 0 else 0:.1f}%</td>
                    <td class="num">{calc_retire_tax(severance_3x, tenure_years)/severance_3x*100 if severance_3x > 0 else 0:.1f}%</td>
                </tr>
            </tbody>
        </table>
        
        <div style="display:flex;gap:16px;margin-bottom:10px;">
            <div style="flex:1;">{retire_pretax_chart}</div>
            <div style="flex:1;">{retire_aftertax_chart}</div>
        </div>
        
        <div class="highlight-box" style="margin-top:4px;margin-bottom:10px;padding:14px 22px;">
            <div class="hl-title">적용 정관배수: {multiplier}배 → 예상 퇴직금 {sev:,.0f}만원 (세후 {sev_net:,.0f}만원, 실효세율 {sev_rate:.1f}%)</div>
            <div class="hl-desc">{'2019년 이전 취임자는 정관배수 3배 적용 가능 (2019.12.31 이전 퇴직금 규정)' if multiplier == 3 else '2020년 이후 취임자는 정관배수 2배로 제한 (세법 개정)'}</div>
        </div>
        
        <div class="warning-box" style="margin-top:8px;padding:10px 14px;font-size:12px;line-height:1.55;">
            ⚠️ <strong>임원퇴직금규정이 없으면</strong> 1년 총급여의 1/10 × 근속기간만 손금산입. 정관배수 2배(2020~) 초과분은 <strong>손금불산입(법인세 추가부담)</strong> → <strong>정관 개정 필요</strong>. 규정 있으면 <strong>최대 3배까지 적용</strong>하여 전액 비용처리 가능.
        </div>

        <h3 class="subsection-title" style="margin-top:8px;">◆ 연봉가정별 예상 퇴직금(세전) 간이 비교</h3>
        <table class="data-table financial-table compact">
            <thead><tr><th>연봉 가정</th><th>당해연도 말 (1배)</th><th>10년 후 (3배)</th></tr></thead>
            <tbody>
                <tr><td class="bold-row">연봉 1.00억원</td><td class="num">{10000/12*tenure_years:,.0f}만원</td><td class="num">{10000/12*tenure_years*3:,.0f}만원</td></tr>
                <tr><td class="bold-row">연봉 1.50억원</td><td class="num">{15000/12*tenure_years:,.0f}만원</td><td class="num">{15000/12*tenure_years*3:,.0f}만원</td></tr>
                <tr><td class="bold-row">연봉 2.50억원</td><td class="num">{25000/12*tenure_years:,.0f}만원</td><td class="num">{25000/12*tenure_years*3:,.0f}만원</td></tr>
            </tbody>
        </table>
    </div>
</div>
"""


